(()=>{
const COURSE_RECEPTORS=Object.freeze({
 'GABA-A':{label:'GABA-A · canal aniónico',kind:'fast',e:-75,ion:'Cl⁻',charge:-1,nt:'gaba'},
 'GABA-B':{label:'GABA-B → Gi/o → GIRK',kind:'meta',e:-90,ion:'K⁺',charge:1,nt:'gaba'},
 NMDA:{label:'NMDA · canal regulado por Mg²⁺',kind:'nmda',e:0,ion:'Cationes, incluido Ca²⁺',charge:1,nt:'glutamate'},
 mGluR1:{label:'mGluR1 → Gq → PLC',kind:'signal',pathway:'gq',e:null,nt:'glutamate'},
 M1:{label:'M1 → Gq → PLC',kind:'signal',pathway:'gq',e:null,nt:'ach'},
 M2:{label:'M2 → Gi/o → GIRK · célula equipada',kind:'meta',e:-90,ion:'K⁺',charge:1,nt:'ach'},
 D1:{label:'D1 → Gs → AMPc',kind:'signal',pathway:'gs',e:null,nt:'dopamine'},
 '5-HT1A':{label:'5-HT1A → Gi/o → GIRK · célula equipada',kind:'meta',e:-90,ion:'K⁺',charge:1,nt:'serotonin'},
 '5-HT2A':{label:'5-HT2A → Gq → PLC',kind:'signal',pathway:'gq',e:null,nt:'serotonin'},
 AMPA:{label:'AMPA · canal catiónico',kind:'fast',e:0,ion:'Cationes',charge:1,nt:'glutamate'},
 nAChR:{label:'Nicotínico · canal catiónico',kind:'fast',e:0,ion:'Cationes',charge:1,nt:'ach'},
 D2:{label:'D2 → Gi/o → GIRK · célula equipada',kind:'meta',e:-90,ion:'K⁺',charge:1,nt:'dopamine'},
 '5-HT3':{label:'5-HT3 · canal catiónico',kind:'fast',e:0,ion:'Cationes',charge:1,nt:'serotonin'}
});
const COURSE_PROFILES=Object.freeze({
 gaba:{name:'GABA',short:'GABA',receptors:['GABA-A','GABA-B'],carrier:'GAT',clearance:'captación neuronal y glial',withdraw:'GABA se dispersa y transportadores GAT lo captan. La enzima GABA-T actúa dentro de la célula, asociada a mitocondrias; no degrada GABA en la hendidura.',scope:'Se comparan GABA-A y la rama postsináptica GABA-B/GIRK; no toda despolarización facilita el disparo.',sources:[['Hamill et al., 1983','https://pubmed.ncbi.nlm.nih.gov/6314144/'],['Fowler et al., 2006/2007','https://pmc.ncbi.nlm.nih.gov/articles/PMC2075413/'],['Roth y Draguhn, 2012 · revisión','https://pmc.ncbi.nlm.nih.gov/articles/PMC3316990/']]},
 glutamate:{name:'Glutamato',short:'Glutamato',receptors:['AMPA','NMDA','mGluR1'],carrier:'EAAT',clearance:'captación por transportadores EAAT',withdraw:'EAAT transporta glutamato hacia neuronas y glía. Captarlo retira transmisor del exterior; no es una degradación enzimática dentro de la hendidura. El ciclo glutamato/glutamina queda fuera.',scope:'AMPA y NMDA se calculan con conductancias reducidas; mGluR1 muestra la vía Gq/PLC cualitativamente. Kainato y otros mGluR quedan para ampliaciones posteriores.',sources:[['Biedermann et al., 2021','https://pubmed.ncbi.nlm.nih.gov/33602810/'],['Qiu y Boudker, 2023','https://www.nature.com/articles/s41467-023-38120-5']]},
 ach:{name:'Acetilcolina',short:'ACh',receptors:['nAChR','M1','M2'],carrier:'CHT · colina',clearance:'hidrólisis por acetilcolinesterasa y captación de colina',withdraw:'La acetilcolinesterasa (AChE) rompe acetilcolina en colina y acetato en el espacio extracelular. CHT capta colina; no se representa la recaptación de acetilcolina intacta como vía principal.',scope:'Se comparan nicotínico, M1 y una rama M2/GIRK en una célula equipada. M3/M4/M5 y otros efectores no se representan; no se reproduce una placa motora completa.',sources:[['Watanabe y Narahashi, 1979','https://doi.org/10.1085/jgp.74.5.615'],['Katz y Miledi, 1973','https://pubmed.ncbi.nlm.nih.gov/4361216/'],['Okuda et al., 2000','https://pubmed.ncbi.nlm.nih.gov/10649566/'],['Xue et al., 2024','https://www.nature.com/articles/s41421-024-00731-7']]},
 dopamine:{name:'Dopamina',short:'Dopamina',receptors:['D2','D1'],carrier:'DAT',clearance:'captación neuronal por DAT',withdraw:'DAT transporta dopamina hacia el interior celular y contribuye a retirar la señal extracelular. Difusión y captación se solapan. El metabolismo posterior no se calcula ni se dibuja como destrucción en la hendidura.',scope:'Escenario D2 en una célula receptora equipada con GIRK; el acoplamiento no se presupone en toda célula D2. D1 muestra Gs y AMPc sin deducir un voltaje. D3/D4/D5, autorreceptores y transmisión por volumen quedan fuera.',sources:[['Lacey et al., 1987','https://pubmed.ncbi.nlm.nih.gov/2451725/'],['Huang et al., 2013 · referencia de acoplamiento','https://pubmed.ncbi.nlm.nih.gov/23942137/'],['Srivastava et al., 2024','https://www.nature.com/articles/s41586-024-07739-9']]},
 serotonin:{name:'Serotonina',short:'5-HT',receptors:['5-HT3','5-HT1A','5-HT2A'],carrier:'SERT',clearance:'captación neuronal por SERT',withdraw:'SERT capta serotonina hacia el interior de la neurona. Captación no significa degradación. La difusión también reduce la disponibilidad local; el metabolismo intracelular queda fuera de este cálculo.',scope:'Se comparan 5-HT3, una rama 5-HT1A/GIRK y la vía 5-HT2A/PLC. No se representan todos los receptores ni un estado emocional.',sources:[['Maricq et al., 1991','https://researchportal.ukhsa.gov.uk/en/publications/primary-structure-and-functional-expression-of-the-5htsub3sub-rec/'],['Yang et al., 2021','https://pmc.ncbi.nlm.nih.gov/articles/PMC8635421/']]}
});
const RECEPTOR_SOURCES=Object.freeze({
 NMDA:[['Nowak et al., 1984 · Mg²⁺ y voltaje','https://www.nature.com/articles/307462a0'],['Jahr y Stevens, 1990 · bloqueo de conductancia','https://pubmed.ncbi.nlm.nih.gov/1697902/'],['Johnson y Ascher, 1987 · glicina','https://www.nature.com/articles/325529a0']],
 mGluR1:[['Masu et al., 1991 · receptor metabotrópico','https://www.nature.com/articles/349760a0'],['Acoplamiento mGluR1/PLC, 1994','https://pubmed.ncbi.nlm.nih.gov/8014896/']],
 M1:[['Wess et al., 1990 · acoplamiento muscarínico','https://pubmed.ncbi.nlm.nih.gov/2172767/'],['Jensen et al., 2009 · M1/Gq/PLC','https://pmc.ncbi.nlm.nih.gov/articles/PMC2699104/']],
 M2:[['M2/GIRK coexpresados, 2000','https://pubmed.ncbi.nlm.nih.gov/10660578/']],
 D1:[['Monsma et al., 1990 · D1 y AMPc','https://www.pnas.org/doi/10.1073/pnas.87.17.6723']],
 '5-HT1A':[['Gadgaard y Jensen, 2020 · 5-HT1A/GIRK','https://pubmed.ncbi.nlm.nih.gov/32088264/']],
 '5-HT2A':[['Goppelt-Struebe y Stroebel, 1998 · 5-HT2A y señalización','https://pubmed.ncbi.nlm.nih.gov/9572479/']]
});
const COURSE_LAST=12;
function receptorRoute(id){const r=COURSE_RECEPTORS[id];if(!r)throw Error('Receptor inválido');
 if(r.kind==='signal')return r.pathway==='gs'?['D1 detecta dopamina','Gs transmite la señal','Adenilil ciclasa se activa','Aumenta AMPc']:['El receptor detecta el transmisor','Gq transmite la señal','PLC actúa sobre PIP₂','Se generan IP₃ y DAG'];
 return r.kind==='meta'?['Unión al receptor','Activación de Gi/o','Gβγ regula un canal GIRK separado','Conductancia K⁺ y respuesta condicionada por gradientes']:[`Unión a ${id}`,id==='NMDA'?'También se requiere coagonista':'Se activa el canal del receptor',id==='NMDA'?'Mg²⁺ bloquea más a voltajes negativos':'La conductancia permite corriente','La corriente cambia el voltaje de la membrana'];
}
function receptorExplanation(id){const r=COURSE_RECEPTORS[id];receptorRoute(id);
 if(r.kind==='signal')return r.pathway==='gs'?'D1 regula una enzima mediante Gs. La adenilil ciclasa produce AMPc, un mensajero dentro de la célula. Aquí se muestra la dirección de esa señal; no se calculan concentraciones, tiempos ni un potencial postsináptico. El efecto sobre canales y voltaje requiere especificar la maquinaria de la célula.':'El receptor usa Gq, una proteína que transmite la señal dentro de la célula. Gq activa PLC (fosfolipasa C), enzima que transforma el lípido PIP₂ y genera los mensajeros IP₃ y DAG. IP₃ puede favorecer salida de Ca²⁺ de depósitos internos: es distinto del calcio que entra al terminal presináptico. La vía es cualitativa; no se deduce un voltaje universal.'+(id==='M1'?' En una célula con canales Kv7, reducir PIP₂ puede disminuir la corriente M de K⁺. Ese efecto se explica aquí, pero no se calcula: faltan los canales y parámetros de esa célula.':'');
 if(id==='NMDA')return 'NMDA contiene un canal catiónico permeable también a Ca²⁺. Se necesita glutamato y un coagonista (aquí, glicina presente). El Mg²⁺ extracelular bloquea más el poro a voltajes negativos. La curva calcula una conductancia neta reducida: no separa Na⁺, K⁺ y Ca²⁺ ni calcula plasticidad.';
 if(r.kind==='meta')return `${id} no contiene un poro. En esta célula equipada con GIRK, Gi/o y Gβγ regulan un canal K⁺ separado. Se calcula solo esa rama con una conductancia lineal: se omite la rectificación de GIRK. Otros efectores, incluida regulación de AMPc, quedan fuera; el acoplamiento no se presupone en todas las células.`;
 return `${id} contiene un canal. Su conductancia neta se calcula en una membrana pasiva. La corriente depende del voltaje y de la reversión; no representa todas las acciones del neurotransmisor ni permite demostrar por sí sola excitación o inhibición de un circuito.`;
}
function courseStage(key,receptor,step){const p=COURSE_PROFILES[key],r=COURSE_RECEPTORS[receptor];if(!p||!p.receptors.includes(receptor)||!Number.isInteger(step)||step<0||step>COURSE_LAST)throw Error('Recorrido inválido');
 const indirect=r.kind==='meta'||r.kind==='signal',signal=r.kind==='signal';
 return [
 ['De la liberación a la respuesta',`Objetivo: seguir ${p.name.toLowerCase()} desde una vesícula hasta ${receptor}, explicar su mecanismo y reconocer cómo termina la señal. Predice antes de avanzar.`],
 ['Llega una señal al terminal','La señal presináptica ya llegó. Aquí estudiamos la comunicación química; el origen del potencial de acción se explora en su módulo separado.'],
 ['Entra calcio al terminal','La despolarización abre canales de Ca²⁺. Su entrada local favorece la fusión de vesículas con la membrana; el dibujo no mide una concentración ni una velocidad.'],
 [`Se libera ${p.name.toLowerCase()}`,'La vesícula se fusiona y libera su contenido al exterior: exocitosis. Los símbolos representan neurotransmisor; no cuentan moléculas ni son una simulación de difusión.'],
 ['El transmisor se dispersa','El movimiento molecular al azar lo distribuye por el espacio extracelular. No hay una trayectoria dirigida que lleve cada molécula hacia un receptor concreto.'],
 [`Se une a ${receptor}`,`La unión ocurre en la cara exterior y puede revertirse. ${indirect?'El receptor no es un poro: la comunicación continuará dentro mediante proteína G.':'El receptor contiene un canal; la unión favorece su activación.'}`],
 [signal?(r.pathway==='gs'?'Gs comunica con una enzima':'Gq comunica con PLC'):indirect?'Gi/o comunica con GIRK':'El canal permite pasar iones',receptorExplanation(receptor)],
 [signal?'La señal continúa dentro de la célula':'La corriente depende del voltaje',signal?`La proteína G ya estaba presente en reposo. ${receptorRoute(receptor).slice(2).join(' → ')}. Estos cambios se muestran como estados cualitativos, no como una curva experimental o una concentración. No equivalen automáticamente a despolarización o hiperpolarización.`:receptor==='NMDA'?'Con glutamato y coagonista, el paso depende además del Mg²⁺ y del voltaje. En el experimento puedes retirar Mg²⁺ o comparar voltajes iniciales. La entrada de Ca²⁺ se ilustra, sin calcular su concentración.':`La dirección depende del voltaje y del potencial de reversión, donde la corriente cambia de signo. El ejemplo de ${r.ion} depende de los gradientes. Los gráficos calculan esa relación en una membrana pasiva.`],
 ['La unión puede terminar','El transmisor puede disociarse. El canal directo deja de activarse; una vía de proteína G puede seguir señalizando después de la separación. No son procesos instantáneos ni obligatoriamente secuenciales.'],
 [key==='ach'?'AChE actúa fuera de la célula':'Retirada del transmisor',p.withdraw],
 [key==='ach'?'Entra colina, no ACh intacta':'La captación cruza una membrana',key==='ach'?'CHT es el transportador de colina. Se distingue de los receptores y de AChE: cada proteína cumple una función diferente en este recorrido.':`${p.carrier} es un transportador, distinto del receptor. Lleva transmisor hacia dentro de la célula en el escenario elegido. Esta escena no calcula la cinética del transporte.`],
 ['Destino intracelular','Tras la captación hay procesamiento y posibles rutas de reutilización. No se calculan esas rutas ni sus proporciones aquí; se evita convertir la retirada de la señal en una destrucción universal en el espacio extracelular.'],
 ['Vuelve a comparar','Al disminuir el transmisor disponible y desactivarse la vía, termina esta respuesta. Cambia el receptor para comparar mecanismos o pasa al experimento y modifica una sola variable para comprobar tu predicción.']
 ][step];
}

const COURSE_PARAMETERS=Object.freeze({cm:1,gLeak:0.05,eLeak:-65,gMax:0.1,alpha:1,beta:0.2,clearance:0.5,inputRate:0.5,pulseStart:20,pulseEnd:22,tauRise:40,tauFall:120,duration:800,dt:0.1,mgScale:4,mgSlope:0.06});
// Reduced equilibrium block: chosen coefficients, not a fit to a particular preparation.
function nmdaAvailable(v,mg=1){if(!Number.isFinite(v)||!Number.isFinite(mg)||mg<0||mg>10)throw Error('Mg o voltaje inválido');return 1/(1+(mg/COURSE_PARAMETERS.mgScale)*Math.exp(-COURSE_PARAMETERS.mgSlope*v));}
function simulateCourse({key='gaba',receptor=COURSE_PROFILES[key]?.receptors[0],release=1,conductance=1,e=COURSE_RECEPTORS[receptor]?.e,dt=0.1,duration=800,mg=1,coagonist=1,initial=-65}={}){
 const p=COURSE_PROFILES[key],r=COURSE_RECEPTORS[receptor],m=COURSE_PARAMETERS;
 if(!p||!p.receptors.includes(receptor)||r.kind==='signal'||![release,conductance,e,dt,duration,mg,coagonist,initial].every(Number.isFinite)||release<0||release>1||conductance<0||conductance>1||e< -100||e>20||dt<=0||dt>0.2||duration<100||duration>1600||duration/dt>64000||mg<0||mg>10||![0,1].includes(coagonist)||initial< -90||initial> -40)throw Error('Parámetro fuera del modelo de curso');
 const count=Math.round(duration/dt);let v=initial,T=0,bound=0,z=0;const data=[];
 for(let i=0;i<=count;i++){
  const t=i*dt,available=r.kind==='nmda'?coagonist*nmdaAvailable(v,mg):1,g=m.gMax*conductance*(r.kind==='meta'?z:bound)*available,current=g*(v-e);
  data.push({t,v,T,bound,z,g,current,available});if(i===count)break;
  const sum=m.gLeak+g,eq=(m.gLeak*initial+g*e)/sum;
  v=eq+(v-eq)*Math.exp(-sum*dt/m.cm);
  const total=m.alpha*T+m.beta,target=m.alpha*T/total;
  z=r.kind==='meta'?bound+(z-bound)*Math.exp(-dt/(bound>z?m.tauRise:m.tauFall)):0;
  bound=target+(bound-target)*Math.exp(-total*dt);
  const input=t>=m.pulseStart-1e-9&&t<m.pulseEnd-1e-9?m.inputRate*release:0;
  T=input/m.clearance+(T-input/m.clearance)*Math.exp(-m.clearance*dt);
 }
 return {key,receptor,e,release,conductance,dt,duration,mg,coagonist,initial,data};
}
function courseSignal(receptor,change='reference'){
 const r=COURSE_RECEPTORS[receptor];if(r?.kind!=='signal'||!['reference','no-transmitter','uncouple'].includes(change))throw Error('Escenario de señalización inválido');
 const labels=receptorRoute(receptor),on=change==='reference';
 return {receptor,change,mode:'conceptual',states:labels.map((label,i)=>({label,active:on||(change==='uncouple'&&i===0)})),conclusion:on?(r.pathway==='gs'?'Aumenta la señal de AMPc.':'Se activa la rama PLC y sus mensajeros IP₃/DAG.'):change==='no-transmitter'?'Sin señal de transmisor, no se activa esta cadena.':'Puede haber unión al receptor, pero al interrumpir su comunicación con proteína G no continúa esta cadena.'};
}
function courseExperiment(key,receptor,change='half-release'){
 if(!COURSE_PROFILES[key]?.receptors.includes(receptor))throw Error('Par incompatible');
 if(COURSE_RECEPTORS[receptor].kind==='signal')return {mode:'conceptual',reference:courseSignal(receptor),changed:courseSignal(receptor,change),change};
 const options={key,receptor},overrides={'reference':{},'half-release':{release:0.5},'block':{conductance:0},'reverse':{e:COURSE_RECEPTORS[receptor]?.e< -65?-45:-90},'no-mg':{mg:0},'no-coagonist':{coagonist:0},'depolarize':{initial:-40}};
 if(!Object.hasOwn(overrides,change)||(['no-mg','no-coagonist','depolarize'].includes(change)&&receptor!=='NMDA'))throw Error('Cambio inválido');return {mode:'numeric',reference:simulateCourse(options),changed:simulateCourse({...options,...overrides[change]}),change};
}
function courseMetrics(run){if(!run.data)throw Error('Esta vía no calcula voltaje');const baseline=run.initial??-65,peak=run.data.reduce((a,d)=>Math.abs(d.v-baseline)>Math.abs(a.v-baseline)?d:a,run.data[0]);return {delta:peak.v-baseline,peak:peak.v,time:peak.t,maxG:Math.max(...run.data.map(d=>d.g))};}
function coursePlot(reference,changed,field='v',cursor=30,window=reference.duration){
 const all=reference.data.concat(changed?changed.data:[]).filter(d=>d.t<=window),isV=field==='v',limit=isV?0:Math.max(0.05,...all.map(d=>Math.abs(d.current)))*1.12;
 const minimum=isV?Math.min(...all.map(d=>d.v)):0,maximum=isV?Math.max(...all.map(d=>d.v)):0,margin=Math.max(1,(maximum-minimum)*0.15);
 const low=isV?minimum-margin:-limit,high=isV?maximum+margin:limit,x=t=>62+t/window*770,y=v=>205-(v-low)/(high-low)*158;
 const line=(run,color,dash)=>`<path d="${run.data.filter(d=>d.t<=window).filter((_,i)=>i%Math.max(1,Math.floor(window/run.dt/900))===0).map((d,i)=>`${i?'L':'M'}${x(d.t).toFixed(2)},${y(d[field]).toFixed(2)}`).join('')}" fill="none" stroke="${color}" stroke-width="2" ${dash?'stroke-dasharray="7 4"':''}/>`;
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 860 260" role="img" aria-label="${isV?'Potencial postsináptico en mV':'Corriente postsináptica en microamperios por centímetro cuadrado'}, tiempo en milisegundos" font-family="Arial" font-size="14" fill="#28483f"><rect width="860" height="260" fill="#fff"/><text x="62" y="24" font-size="18">${isV?'Potencial postsináptico · mV':'Corriente postsináptica · µA/cm²'}</text>${Array.from({length:5},(_,i)=>{const val=low+(high-low)*i/4;return `<path d="M62,${y(val)}H832" stroke="#dce5df"/><text x="3" y="${y(val)+4}">${isV?val.toFixed(1):val.toFixed(2)}</text>`;}).join('')}${[0,window/4,window/2,window*3/4,window].map(t=>`<text x="${x(t)-6}" y="228">${t}</text>`).join('')}<path d="M62,47V205H832" stroke="#58776b" fill="none"/>${line(reference,'#7e8f86',true)}${changed?line(changed,'#28689b',false):''}<path d="M${x(cursor)},47V205" stroke="#a86b22" stroke-dasharray="3 4"/><text x="719" y="251">Tiempo (ms)</text></svg>`;
}

function renderCourse(key,receptor,step){
 const p=COURSE_PROFILES[key],r=COURSE_RECEPTORS[receptor];courseStage(key,receptor,step);
 const meta=r.kind==='meta',signal=r.kind==='signal',indirect=meta||signal,gname=signal?(r.pathway==='gs'?'Gs':'Gq'):'Gi/o',bound=step>=5&&step<=7,active=step>=6&&step<=(meta?9:7),freed=step>=3&&step<=8,conducting=!signal&&active&&(!meta||step>=7);
 const label=(x,y,t,size=18)=>`<text x="${x}" y="${y}" font-family="Arial" font-size="${size}" fill="#294a40">${t}</text>`;
 const bead=(x,y,color='#d89c39',tag='transmitter')=>`<circle data-particle="${tag}" cx="${x}" cy="${y}" r="6" fill="${color}" stroke="#ffffff" stroke-width=".6"/>`;
 const vesicle=(x,y)=>`<circle cx="${x}" cy="${y}" r="31" fill="url(#course-vesicle)" stroke="#739a79" stroke-width="3"/>${[[-10,-8],[8,-10],[0,7],[-11,13]].map(([a,b])=>bead(x+a,y+b)).join('')}`;
 const channel=(x,open)=>`<g data-channel="${meta?'GIRK':receptor}" transform="translate(${x} 366)"><rect x="-6" y="-18" width="12" height="48" fill="${open?'#fff':'#6d9584'}"/><path d="M-21,-34Q-40,-11 -24,28Q-16,45 -6,27V-12Q-7,-37 -21,-34Z M21,-34Q40,-11 24,28Q16,45 6,27V-12Q7,-37 21,-34Z" fill="url(#course-protein)" stroke="#527f72" stroke-width="2"/></g>`;
 const lipid=x=>`<g stroke="#6d9385" stroke-width="1"><path d="M${x-2},198v13m4,-13v13 M${x-2},359v14m4,-14v14"/><ellipse cx="${x}" cy="195" rx="5" ry="4" fill="#afc9ae"/><ellipse cx="${x}" cy="216" rx="5" ry="4" fill="#afc9ae"/><ellipse cx="${x}" cy="355" rx="5" ry="4" fill="#a8c6b5"/><ellipse cx="${x}" cy="377" rx="5" ry="4" fill="#a8c6b5"/></g>`;
 const carrier=(x,y)=>`<g data-clearance="${p.carrier}" transform="translate(${x} ${y})"><path d="M-12,-17Q-25,0 -12,17H-2V-17Z M12,-17Q25,0 12,17H2V-17Z" fill="#b29cc1" stroke="#80678e" stroke-width="2"/></g>`;
 const gp=indirect?`<g data-protein="${gname}" data-state="${active?'active':'resting'}"><path d="M507,399L555,428" fill="none" stroke="#648e99" stroke-width="2"/><g data-subunit="alpha" transform="translate(${signal&&active?116:0} 0)"><ellipse cx="580" cy="430" rx="28" ry="20" fill="url(#course-protein)"/>${label(567,436,signal?(r.pathway==='gs'?'αs':'αq'):'α',16)}</g><g transform="translate(${meta&&active?43:0} 0)"><ellipse cx="621" cy="430" rx="20" ry="16" fill="#8cb4b5"/><ellipse cx="644" cy="419" rx="10" ry="12" fill="#bbd5c4"/>${label(615,435,'β')}${label(640,424,'γ',14)}</g>${active?`<path d="${signal?'M726,425L755,411':'M705,425L741,402'}" stroke="#65859d" stroke-width="3"/>`:''}${label(530,503,active?`${gname} activa`:`${gname} · αβγ en reposo`,16)}</g>`:'';
 const receptorShape=`<g data-receptor="${receptor}" transform="translate(490 366)"><path d="M-30,-36Q-48,-74 -16,-67L0,-43Q22,-82 40,-55Q57,-31 27,-16L20,25Q1,55 -18,27L-25,-4Z" fill="url(#course-protein)" stroke="#567e76" stroke-width="2"/></g>`;
 const enzyme=signal?`<g data-effector="${r.pathway==='gs'?'adenylyl-cyclase':'PLC'}"><ellipse cx="800" cy="${r.pathway==='gs'?368:406}" rx="44" ry="24" fill="${active?'#9cbfa5':'#d0dcd2'}" stroke="#628878" stroke-width="2"/>${label(782,r.pathway==='gs'?374:412,r.pathway==='gs'?'AC':'PLC',17)}${label(755,454,r.pathway==='gs'?'Adenilil ciclasa':'Fosfolipasa C',17)}${active?label(738,492,r.pathway==='gs'?'AMPc ↑ · mensajero':'IP₃ + DAG · mensajeros',16):label(745,492,'Enzima en reposo',16)}</g>`:'';
 const post=indirect?`${receptorShape}${signal?enzyme:channel(780,conducting)}${gp}${label(429,474,receptor,20)}${meta?label(741,474,'GIRK · K⁺',20):''}`:`${channel(520,conducting)}${label(479,450,receptor,22)}${label(402,478,'El receptor contiene el canal',17)}`;
 const clear=key==='ach'?`${step>=9&&step<=11?`<g data-enzyme="AChE-extracellular"><ellipse cx="760" cy="267" rx="45" ry="24" fill="#d6c4aa" stroke="#a38e74" stroke-width="2"/>${label(732,272,'AChE')}${label(663,306,'Colina + acetato',16)}<path d="M670,267H707M808,267H847" stroke="#9a8173" stroke-width="2"/>${bead(862,267,'#739db3','choline')}<rect x="881" y="262" width="9" height="9" fill="#9a7fac"/></g>`:''}`:'';
 const intake=step===10?`<g data-uptake="${key==='ach'?'choline':key}"><path d="M150,263V157m-6,9l6,-9l6,9" fill="none" stroke="#8a6c9b" stroke-width="3"/>${bead(150,184,key==='ach'?'#739db3':'#d89c39',key==='ach'?'choline':'transmitter')}${label(26,280,key==='ach'?'CHT capta colina':`${p.carrier}: captación hacia dentro`,16)}</g>`:'';
 const netFlow=conducting?`<g data-flow="${meta?'K-out':receptor==='GABA-A'?'Cl-in':'cation-net-in'}"><path d="M${meta?780:520},${meta?421:297}V${meta?297:421}" stroke="#28699b" stroke-width="3"/><path d="M${(meta?780:520)-6},${meta?307:411}l6,${meta?-10:10}l6,${meta?10:-10}" stroke="#28699b" fill="none" stroke-width="3"/>${label(meta?817:552,333,meta?'K⁺ sale':receptor==='GABA-A'?'Cl⁻ entra · corriente saliente':receptor==='NMDA'?'Flujo limitado por Mg²⁺':'Corriente neta entrante',16)}</g>`:'';
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1060 560" role="img" aria-label="${p.name}: ${courseStage(key,receptor,step)[0]}. Corte ilustrativo sin escala."><defs><linearGradient id="course-pre" x2=".2" y2="1"><stop stop-color="#afccbd"/><stop offset="1" stop-color="#e0e5c6"/></linearGradient><linearGradient id="course-post" x2=".2" y2="1"><stop stop-color="#cedfd3"/><stop offset="1" stop-color="#a7c6c0"/></linearGradient><radialGradient id="course-vesicle" cx=".3" cy=".3"><stop stop-color="#fffad8"/><stop offset="1" stop-color="#abc695"/></radialGradient><linearGradient id="course-protein"><stop stop-color="#5a8e80"/><stop offset=".5" stop-color="#b3cdae"/><stop offset="1" stop-color="#577d8b"/></linearGradient></defs><rect width="1060" height="560" rx="20" fill="#f9f6ec"/><path d="M0,0H950Q1010,126 920,205H0Z" fill="url(#course-pre)"/><path d="M0,366H920Q987,476 933,560H0Z" fill="url(#course-post)"/>${key==='glutamate'?`<path d="M1060,170Q972,206 991,290Q960,350 1020,405H1060Z" fill="#c6c8d8" stroke="#9dacc0"/>${carrier(995,285)}${label(1003,218,'Glía',16)}${label(994,335,'EAAT',16)}${step===10?'<path d="M947,285H1024m-9,-6l9,6l-9,6" stroke="#8a6c9b" fill="none" stroke-width="3"/>':''}`:''}${Array.from({length:51},(_,i)=>lipid(i*18)).join('')}${label(25,37,'TERMINAL PRESINÁPTICO',18)}${label(25,315,'ESPACIO EXTRACELULAR',16)}${label(25,437,'CÉLULA RECEPTORA',17)}${vesicle(280,108)}${step<3?vesicle(480,161):''}${step===3?'<path d="M449,205C459,182 438,140 459,126Q491,103 511,137C524,163 503,186 511,205" fill="url(#course-vesicle)" stroke="#719a78" stroke-width="3"/>':''}${step===1?label(618,118,'Llega la señal presináptica'):''}${label(335,142,'Canal Ca²⁺',16)}<path d="M362,181V228M382,181V228" stroke="#6a91a2" stroke-width="12"/>${step===2?'<path d="M371,260V161m-6,9l6,-9l6,9" stroke="#2d719b" fill="none" stroke-width="3"/>':''}${carrier(150,205)}${label(55,124,p.carrier,16)}${freed?[[475,247],[516,274],[603,254],[402,292],[700,238]].map(([x,y])=>bead(x,y)).join(''):''}${step===9&&key!=='ach'?`${bead(46,253)}${bead(873,252)}${label(35,270,'Difusión y captación reducen disponibilidad',16)}`:''}${post}${bound?bead(indirect?470:497,indirect?310:333):''}${netFlow}${receptor==='NMDA'&&bound?`<g data-coagonist="glycine">${bead(543,333,'#739db3','glycine')}<path d="M549,329L620,289" stroke="#739db3" fill="none"/>${label(628,287,'Glicina · coagonista',16)}</g><g data-block="Mg-equilibrium"><circle cx="520" cy="366" r="7" fill="#a182ac"/>${label(555,409,'Mg²⁺ · bloqueo parcial',16)}</g>`:''}${clear}${intake}${step===11?label(68,76,key==='ach'?'Colina captada · resíntesis no calculada':'Transmisor captado · destinos no calculados',17):''}${label(25,535,`${p.short} · símbolos y posiciones ilustrativos; las etapas no son milisegundos`,16)}</svg>`;
}

const c=id=>document.getElementById(id),key=document.body.dataset.course,profile=COURSE_PROFILES[key];
if(profile){
 let receptor=profile.receptors[0],step=0,playing=false,timer=null,zoomed=false,windowMs=100,experiment,compared=false;
 const signal=()=>COURSE_RECEPTORS[receptor].kind==='signal';
 const options=items=>items.map(([value,label])=>`<option value="${value}">${label}</option>`).join('');
 c('c-receptor').innerHTML=options(profile.receptors.map(id=>[id,COURSE_RECEPTORS[id].label]));
 c('c-receptor-map').innerHTML=`<div class="table-scroll" tabindex="0" role="region" aria-label="Comparación de mecanismos por receptor"><table><caption>Receptores de ${profile.name}: mecanismo y alcance</caption><thead><tr><th>Receptor</th><th>Vía representada</th><th>Resultado disponible</th></tr></thead><tbody>${profile.receptors.map(id=>{const r=COURSE_RECEPTORS[id];return `<tr><th scope="row">${id}</th><td>${r.kind==='signal'?r.pathway==='gs'?'Gs → adenilil ciclasa → AMPc':'Gq → PLC → IP₃/DAG':r.kind==='meta'?'Gi/o → Gβγ → GIRK':id==='NMDA'?'Canal + coagonista + bloqueo por Mg²⁺':'Canal directo'}</td><td>${r.kind==='signal'?'Estados cualitativos; sin voltaje calculado':'Voltaje y corriente del modelo reducido'}</td></tr>`;}).join('')}</tbody></table></div>`;
 function stop(){if(timer!==null)clearInterval(timer);timer=null;playing=false;}
 function storyPaint(){if(key==='gaba')return;
  const [title,text]=courseStage(key,receptor,step);c('c-title').textContent=title;c('c-text').textContent=text;c('c-picture').innerHTML=renderCourse(key,receptor,step);
  c('c-step-label').textContent=`Etapa ${step+1} de ${COURSE_LAST+1} · ${playing?'reproduciendo':'pausada'}`;c('c-prev').disabled=step===0;c('c-next').disabled=step===COURSE_LAST;c('c-play').textContent=playing?'Pausar':'Reproducir';
 }
 const stateCard=(run,title)=>`<article><h3>${title}</h3><ol class="signal-path">${run.states.map(s=>`<li class="${s.active?'signal-on':'signal-off'}">${s.label}<span>${s.active?'Activación de esta rama':'Sin activación de esta rama'}</span></li>`).join('')}</ol><p>${run.conclusion}</p></article>`;
 function graphPaint(){
  if(signal()){c('c-signal-picture').innerHTML=stateCard(experiment.reference,'Referencia')+(compared?stateCard(experiment.changed,'Cambio seleccionado'):'');c('c-plot').innerHTML='';c('c-current').innerHTML='';return;}
  const cursor=+c('c-time').value;c('c-plot').innerHTML=coursePlot(experiment.reference,compared?experiment.changed:null,'v',cursor,windowMs);c('c-current').innerHTML=coursePlot(experiment.reference,compared?experiment.changed:null,'current',cursor,windowMs);
  const run=compared?experiment.changed:experiment.reference,d=run.data[Math.min(run.data.length-1,Math.round(cursor/run.dt))];
  c('c-snapshot').textContent=`${cursor.toFixed(1)} ms del modelo · Vm ${d.v.toFixed(2)} mV · I ${d.current.toFixed(3)} µA/cm² · g ${d.g.toFixed(4)} mS/cm². Receptor ${receptor}. Reposo del escenario ${run.initial} mV. ${receptor==='NMDA'?`Mg²⁺ ${run.mg} mM; coagonista ${run.coagonist?'presente':'ausente'}; fracción disponible ${(d.available*100).toFixed(1)} %.`:COURSE_RECEPTORS[receptor].kind==='meta'?'Rama K⁺ lineal idealizada; se omite la rectificación GIRK.':'Conductancia postsináptica reducida.'}`;
 }
 function setWindow(){windowMs=+c('c-window').value;c('c-time').max=String(windowMs);c('c-time').value=String(Math.min(windowMs,+c('c-time').value));graphPaint();}
 function reference(){compared=false;experiment=courseExperiment(key,receptor,'reference');c('c-result').textContent=signal()?`Referencia conceptual de ${receptor}: sigue los estados de la cadena. Se representan presencia y dirección de la señal, sin calcular concentraciones ni voltajes.`:`Referencia medida para ${receptor}: reversión ${experiment.reference.e} mV. Predice, cambia una variable y compara. Las cinéticas son elecciones del modelo; no comparan tiempos reales entre neurotransmisores.`;graphPaint();}
 function configure(){
  const r=COURSE_RECEPTORS[receptor];c('c-receptor').value=receptor;c('c-numeric').hidden=signal();c('c-signal').hidden=!signal();c('c-nmda').hidden=receptor!=='NMDA';
  c('c-experiment-title').textContent=signal()?`2. Señalización intracelular · ${receptor}`:`2. Potenciales y corrientes postsinápticas · ${receptor}`;
  c('c-route-description').textContent=receptorExplanation(receptor);c('c-route-scope').textContent=profile.scope;c('c-route-map').innerHTML=receptorRoute(receptor).map(t=>`<li>${t}</li>`).join('');
  c('c-route-sources').innerHTML=(RECEPTOR_SOURCES[receptor]||profile.sources).map(([label,url])=>`<a href="${url}">${label}</a>`).join(' · ');
  c('c-experiment-help').textContent=signal()?'Predice si la cadena continuará. Mide la referencia y cambia solo presencia de transmisor o acoplamiento con proteína G. Observa qué eslabones siguen activos y explica por qué no se puede deducir un voltaje.':'Mide la referencia gris, predice y compara. Observa voltaje y corriente. Mueve el cursor: la línea naranja y la lectura numérica corresponden a la misma muestra. Cada cambio modifica una sola variable.';
  c('c-prediction').innerHTML=options(signal()?[['','Elige antes de comparar'],['stopped','La señal se interrumpirá antes del mensajero'],['continue','La cadena conservará su activación']]:[['','Elige antes de comparar'],['less','La desviación del reposo será menor'],['more','La desviación del reposo será mayor'],['direction','La desviación cambiará de dirección'],['same','Se reproducirá la referencia']]);c('c-prediction').value='';
  c('c-change').innerHTML=options(signal()?[['uncouple','Interrumpir acoplamiento receptor–proteína G'],['no-transmitter','Retirar la señal de transmisor'],['reference','Mantener referencia']]:[['half-release','Liberar 50 % de la entrada de referencia'],['block','Conductancia de esta vía 0 %'],['reverse','Cambiar solo la reversión'],...(receptor==='NMDA'?[['no-mg','Retirar Mg²⁺: 1 → 0 mM'],['no-coagonist','Retirar coagonista: presente → ausente'],['depolarize','Cambiar reposo del escenario: −65 → −40 mV']]:[]),['reference','Mantener referencia']]);c('c-change').value=signal()?'uncouple':'half-release';
  windowMs=r.kind==='meta'?800:100;c('c-window').value=String(windowMs);c('c-time').max=String(windowMs);c('c-time').value='30';
  c('c-nmda-values').textContent=`A Mg²⁺ = 1 mM, fracción disponible del modelo: −65 mV ${(100*nmdaAvailable(-65)).toFixed(1)} %; −40 mV ${(100*nmdaAvailable(-40)).toFixed(1)} %; 0 mV ${(100*nmdaAvailable(0)).toFixed(1)} %. A Mg²⁺ = 0 mM vale 100 %. Se necesita además activación por transmisor y coagonista.`;
  reference();storyPaint();
 }
 c('c-reference').onclick=reference;
 c('c-compare').onclick=()=>{
  if(!c('c-prediction').value){c('c-result').textContent='Elige una predicción antes de comparar y observa el porqué del resultado.';c('c-prediction').focus();return;}
  const change=c('c-change').value;experiment=courseExperiment(key,receptor,change);compared=true;
  if(signal()){const expected=change==='reference'?'continue':'stopped';c('c-result').textContent=`${c('c-prediction').value===expected?'Tu predicción coincide.':'Compara el resultado con tu predicción.'} ${experiment.changed.conclusion} Es una comparación cualitativa: no se asignan amplitudes, tiempos biológicos ni un potencial a esos estados.`;graphPaint();return;}
  const a=courseMetrics(experiment.reference),b=courseMetrics(experiment.changed),expected=change==='reverse'?'direction':change==='reference'?'same':Math.abs(b.delta)>Math.abs(a.delta)?'more':'less';
  const why={'reverse':'Cambiar la reversión invierte la dirección respecto al reposo sin cambiar el neurotransmisor.','block':'Sin conductancia de esta vía no hay corriente postsináptica, aunque siga presente el transmisor.','half-release':'Menos entrada activa menos la vía en este modelo; la respuesta no tiene por qué reducirse exactamente a la mitad.','reference':'Con parámetros iguales se reproduce la referencia.','no-mg':'Retirar Mg²⁺ elimina este bloqueo del poro; siguen siendo necesarios transmisor y coagonista.','no-coagonist':'Sin coagonista se anula la conductancia NMDA en este modelo, aunque haya glutamato.','depolarize':'A voltajes menos negativos disminuye el bloqueo por Mg²⁺. También cambia la fuerza impulsora. Se comparan desviaciones respecto al reposo propio de cada escenario; no es un experimento de fijación de voltaje.'}[change];
  c('c-result').textContent=`${c('c-prediction').value===expected?'Tu predicción coincide.':'Compara el resultado con tu predicción.'} Cambio máximo desde el reposo de cada escenario: referencia ${a.delta.toFixed(2)} mV; cambio ${b.delta.toFixed(2)} mV. ${why} La membrana es pasiva: no puede disparar ni demostrar excitabilidad.`;graphPaint();
 };
 c('c-receptor').onchange=()=>{stop();receptor=c('c-receptor').value;step=0;configure();};
 c('c-time').oninput=graphPaint;c('c-window').onchange=setWindow;
 c('c-reset').onclick=()=>{stop();receptor=profile.receptors[0];step=0;configure();};
 if(key!=='gaba'){
  c('c-prev').onclick=()=>{stop();step=Math.max(0,step-1);storyPaint();};c('c-next').onclick=()=>{stop();step=Math.min(COURSE_LAST,step+1);storyPaint();};
  const start=()=>{stop();playing=true;if(step===COURSE_LAST)step=0;timer=setInterval(()=>{step=Math.min(COURSE_LAST,step+1);if(step===COURSE_LAST)stop();storyPaint();},3500/+c('c-speed').value);storyPaint();};
  c('c-play').onclick=()=>{if(playing){stop();storyPaint();}else start();};c('c-speed').onchange=()=>{if(playing)start();};
  c('c-restart').onclick=()=>{stop();step=0;c('c-story-prediction').value='';c('c-story-feedback').textContent='Haz una predicción y contrástala con la escena.';storyPaint();};
  c('c-zoom').onclick=()=>{zoomed=!zoomed;c('c-picture').className=zoomed?'scene-scroll is-zoomed':'scene-scroll';c('c-zoom').setAttribute('aria-pressed',String(zoomed));c('c-zoom').textContent=zoomed?'Ver corte completo':'Ampliar dibujo';};
  c('c-story-check').onclick=()=>{const answer=c('c-story-prediction').value;c('c-story-feedback').textContent=!answer?'Elige una predicción antes de comprobar.':answer==='receptor'?'Coincide: un canal directo y una vía por proteína G actúan de manera distinta; el receptor y la maquinaria celular determinan qué respuesta puede calcularse. La retirada depende también del transmisor.':'Revisa el receptor y su mecanismo. Una señal intracelular no equivale automáticamente a un voltaje; tampoco hay una polaridad universal del transmisor.';};
 }
 configure();
}

})();
